        g[v].push_back(u);
    }

    vector<bool> visited(n, false);
    long long total_path = 1LL * n * (n - 1) / 2;
    long long same_path = 0;
    long long ans = 0;

    for (int i = 0; i < n; ++i) {
        if (!visited[i]) {
            int val = a[i];
            int cnt = 0;
            vector<int> stack;
            stack.push_back(i);
            visited[i] = true;
            while (!stack.empty()) {
                int u = stack.back();
                stack.pop_back();
                ++cnt;
                for (int v : g[u]) {
                    if (!visited[v] && a[v] == val) {
                        visited[v] = true;
                        stack.push_back(v);
                    }
                }
            }
            long long block_path = 1LL * cnt * (cnt - 1) / 2;
            ans += block_path * val;
            same_path += block_path;
        }
